import React, { useEffect, useMemo, useRef, useState } from "react";
import "../styles/battle.css";
import { cards } from "../data/cards";

/* ========= ルール関数 ========= */
// カードの色ごとの軽減シンボル合計を計算
function getAvailableReductionsFromBoard(zones) {
  const sum = { red: 0, blue: 0, green: 0, white: 0, yellow: 0, purple: 0 };
  for (const z of zones) {
    if (!z || !z.card) continue;
    const { symbolColor, symbolCount = 1 } = z.card;
    sum[symbolColor] = (sum[symbolColor] || 0) + symbolCount;
  }
  return sum;
}

// 軽減後の実コストを計算
function calcActualCost(card, availableReductions) {
  let reduce = 0;
  for (const color of Object.keys(card.reduction || {})) {
    const need = card.reduction[color] || 0;
    const have = availableReductions[color] || 0;
    reduce += Math.min(need, have);
  }
  return Math.max(0, (card.cost || 0) - reduce);
}

// 現在のコア数からレベル情報を取得
function levelFromCores(card, cores) {
  let current = card.levels[0];
  for (const lvInfo of card.levels) if (cores >= lvInfo.core) current = lvInfo;
  return current; // {lv, core, bp}
}

// ベースBPを取得（能力を含まない）
function getBaseBP(z) {
  if (!z) return 0;
  const info = levelFromCores(z.card, z.cores);
  return info.bp || 0;
}

/* ========= 特殊能力（アタック時） ========= */
// アタック時のBPを能力込みで計算
function getAttackBP(zone) {
  let bp = getBaseBP(zone);
  if (!zone || !zone.card) return bp;
  const card = zone.card;
  // 現在レベル
  const lv = levelFromCores(card, zone.cores).lv;
  // ドラグロン：レベル1または2でアタックしたらBP+2000
  if (card.id === "draguron-001" && (lv === 1 || lv === 2)) {
    bp += 2000;
  }
  return bp;
}

// ブロック強制判定：攻撃カードがジークヴルム（id=siegwurm-001）かつレベル1〜3で、相手の盤面に疲労していないスピリットがある
function mustForceBlock(attackerZone, attackerSide, meRef, opRef) {
  if (!attackerZone || !attackerZone.card) return false;
  const { card, cores } = attackerZone;
  const lv = levelFromCores(card, cores).lv;
  if (card.id !== "siegwurm-001") return false;
  // いずれのLvでも適用（Lv1〜3）
  if (lv < 1 || lv > 3) return false;
  // 相手側の盤面を取得
  const defender = attackerSide === "me" ? opRef.current : meRef.current;
  return defender.zones.some((z) => z && !z.exhausted);
}

/* ========= 簡易AI（メインステップ用） ========= */
function evalSide(side) {
  let s = 0;
  for (const z of side.zones) {
    if (!z) continue;
    const lv = levelFromCores(z.card, z.cores);
    s += (lv.bp || 0) / 1000 + (z.card.symbolCount || 1) * 2;
  }
  s += side.reserve * 0.3 + side.life * 5;
  return s;
}
function evaluate(state) {
  return evalSide(state.op) - evalSide(state.me);
}
// メインステップ用シミュレーター（召喚/レベルアップのみ）
function simulateMain(state, move) {
  const c = structuredClone(state);
  const you = c.op;
  switch (move.type) {
    case "SUMMON": {
      const card = c.opHand[move.handIndex];
      you.reserve -= move.pay.totalPay;
      you.trash += move.pay.actualCost;
      you.zones[move.zoneIndex] = { card, cores: move.pay.needCores, exhausted: false };
      c.opHand.splice(move.handIndex, 1);
      break;
    }
    case "LEVEL_UP": {
      const z = you.zones[move.zoneIndex];
      z.cores += move.needMore;
      you.reserve -= move.needMore;
      break;
    }
    default:
      break;
  }
  return c;
}
function generateLegalMainMoves(state) {
  const moves = [];
  const you = state.op;
  // SUMMON
  const emptyIdx = you.zones.map((z, i) => (z ? null : i)).filter((i) => i !== null);
  const reductions = getAvailableReductionsFromBoard(you.zones);
  state.opHand.forEach((card, handIndex) => {
    const actualCost = calcActualCost(card, reductions);
    const needCores = card.levels?.[0]?.core ?? 0;
    const totalPay = actualCost + needCores;
    if (you.reserve >= totalPay) {
      for (const zoneIndex of emptyIdx) {
        moves.push({ type: "SUMMON", handIndex, zoneIndex, pay: { actualCost, needCores, totalPay } });
      }
    }
  });
  // LEVEL_UP
  you.zones.forEach((z, zoneIndex) => {
    if (!z) return;
    const now = levelFromCores(z.card, z.cores);
    const arr = z.card.levels || [];
    const pos = arr.findIndex((l) => l.lv === now.lv);
    const next = arr[pos + 1];
    if (!next) return;
    const needMore = next.core - z.cores;
    if (needMore > 0 && you.reserve >= needMore) moves.push({ type: "LEVEL_UP", zoneIndex, needMore });
  });
  return moves;
}
function chooseBestMainMove(state) {
  const legal = generateLegalMainMoves(state);
  if (legal.length === 0) return null;
  let best = null;
  let bestScore = -Infinity;
  for (const mv of legal) {
    const sc = evaluate(simulateMain(state, mv));
    if (sc > bestScore) {
      bestScore = sc;
      best = mv;
    }
  }
  return best;
}

/* =================== コンポーネント =================== */
export default function Battle() {
  // 20枚デッキ（プレイヤー/AI共通内容）
  const fullDeck = useMemo(() => {
    const deck = [];
    for (let i = 0; i < 20; i++) deck.push({ ...cards[i % cards.length], deckIndex: i });
    return deck;
  }, []);

  // 試合状態（初期ライフ=3）
  const [me, setMe] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null], cTrash: [] });
  const [op, setOp] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null], cTrash: [] });
  const [deck, setDeck] = useState([]);
  const [hand, setHand] = useState([]);
  const [opDeck, setOpDeck] = useState([]);
  const [opHand, setOpHand] = useState([]);

  // フェーズ管理（0:コア→1:ドロー→2:リフレッシュ→3:メイン→4:アタック）
  const [phase, setPhase] = useState(0);
  const [selectedHandIndex, setSelectedHandIndex] = useState(null);
  const [aiLog, setAiLog] = useState([]);

  // ブロック選択ダイアログ用ステート
  const [blockPrompt, setBlockPrompt] = useState(null);
  const blockResolverRef = useRef(null);

  // 最新参照保存
  const meRef = useRef(me);
  const opRef = useRef(op);
  useEffect(() => { meRef.current = me; }, [me]);
  useEffect(() => { opRef.current = op; }, [op]);

  // 初期ドロー
  useEffect(() => {
    const d1 = [...fullDeck];
    const d2 = [...fullDeck];
    const drawN = (d, n) => {
      const out = [];
      for (let i = 0; i < n && d.length; i++) {
        const idx = Math.floor(Math.random() * d.length);
        out.push(d.splice(idx, 1)[0]);
      }
      return [out, d];
    };
    const [m4, nd1] = drawN(d1, 4);
    const [o4, nd2] = drawN(d2, 4);
    setDeck(nd1);
    setHand(m4);
    setOpDeck(nd2);
    setOpHand(o4);
  }, [fullDeck]);

  /* ---------- 共通ヘルパ ---------- */
  // スピリットを破壊してカードトラッシュへ、コアをリザーブに返却
  const destroySpirit = (owner, zoneIndex) => {
    if (owner === "me") {
      setMe((m) => {
        const z = m.zones[zoneIndex];
        if (!z) return m;
        const newZones = m.zones.map((zz, i) => (i === zoneIndex ? null : zz));
        return { ...m, reserve: m.reserve + z.cores, zones: newZones, cTrash: [...m.cTrash, z.card] };
      });
    } else {
      setOp((o) => {
        const z = o.zones[zoneIndex];
        if (!z) return o;
        const newZones = o.zones.map((zz, i) => (i === zoneIndex ? null : zz));
        return { ...o, reserve: o.reserve + z.cores, zones: newZones, cTrash: [...o.cTrash, z.card] };
      });
    }
  };

  // 疲労状態にする
  const markExhausted = (owner, zoneIndex) => {
    if (owner === "me") {
      setMe((m) => ({ ...m, zones: m.zones.map((z, i) => (i === zoneIndex && z ? { ...z, exhausted: true } : z)) }));
    } else {
      setOp((o) => ({ ...o, zones: o.zones.map((z, i) => (i === zoneIndex && z ? { ...z, exhausted: true } : z)) }));
    }
  };

  // ノーブロック時のダメージ処理（ライフ減少分をRESERVE増加に変換）
  const applyUnblockedDamage = (defender, symbols, attackerSide, attackerZone) => {
    if (defender === "op") {
      setOp((o) => {
        const newLife = Math.max(0, o.life - symbols);
        const delta = o.life - newLife;
        return { ...o, life: newLife, reserve: o.reserve + delta };
      });
    } else {
      setMe((m) => {
        const newLife = Math.max(0, m.life - symbols);
        const delta = m.life - newLife;
        return { ...m, life: newLife, reserve: m.reserve + delta };
      });
    }
    markExhausted(attackerSide, attackerZone);
  };

  // バトル解決（ブロック有り）。customAtkBP指定で攻撃者のBPを上書き可
  const resolveBattle = (attackerSide, attackerZone, blockerZone, customAtkBP = null) => {
    const atkOwner = attackerSide;
    const defOwner = attackerSide === "me" ? "op" : "me";
    const atkState = atkOwner === "me" ? meRef.current : opRef.current;
    const defState = defOwner === "me" ? meRef.current : opRef.current;
    const atkZ = atkState.zones[attackerZone];
    const blkZ = defState.zones[blockerZone];
    if (!atkZ || !blkZ) {
      // 攻撃者またはブロッカーが存在しない場合、疲労だけ適用
      markExhausted(attackerSide, attackerZone);
      if (blkZ) markExhausted(defOwner, blockerZone);
      return;
    }
    const atkBP = customAtkBP !== null ? customAtkBP : getBaseBP(atkZ);
    const blkBP = getBaseBP(blkZ);
    // BP同値：双方破壊、以下：敗者破壊
    const atkDestroyed = blkBP >= atkBP;
    const blkDestroyed = atkBP >= blkBP;
    markExhausted(defOwner, blockerZone);
    markExhausted(attackerSide, attackerZone);
    if (atkDestroyed) destroySpirit(atkOwner, attackerZone);
    if (blkDestroyed) destroySpirit(defOwner, blockerZone);
  };

  // ブロック選択を待つプロンプト（forcedBlock=trueでブロック必須）
  const waitForBlockChoice = (attackerSide, attackerZone, attackerBP, attackerSymbols, forcedBlock = false) =>
    new Promise((resolve) => {
      // 古いプロンプトが残っていれば閉じる
      if (blockResolverRef.current) {
        try {
          blockResolverRef.current({ type: "none" });
        } catch (e) {}
      }
      blockResolverRef.current = resolve;
      setBlockPrompt({
        defender: attackerSide === "me" ? "op" : "me",
        attackerSide,
        attackerZone,
        attackerBP,
        attackerSymbols,
        forcedBlock,
      });
    });

  // プロンプトを閉じる
  const closeBlockPrompt = () => {
    setBlockPrompt(null);
    blockResolverRef.current = null;
  };

  /* ---------- 自分の操作 ---------- */
  const canSummon = phase === 3;
  const canAttack = phase === 4;

  const nextStep = () => {
    if (phase === 0) {
      setMe((m) => ({ ...m, reserve: m.reserve + 1 }));
    } else if (phase === 1) {
      if (deck.length > 0) {
        const idx = Math.floor(Math.random() * deck.length);
        const c = deck[idx];
        const nd = [...deck];
        nd.splice(idx, 1);
        setDeck(nd);
        setHand((h) => [...h, c]);
      }
    } else if (phase === 2) {
      setMe((m) => ({
        ...m,
        reserve: m.reserve + m.trash,
        trash: 0,
        zones: m.zones.map((z) => (z ? { ...z, exhausted: false } : z)),
      }));
    }
    setPhase((p) => Math.min(4, p + 1));
  };

  const onHandClick = (i) => setSelectedHandIndex((prev) => (prev === i ? null : i));

  const summonToZone = (zoneIdx) => {
    if (!canSummon) return;
    if (selectedHandIndex === null) return;
    if (me.zones[zoneIdx] !== null) return;
    const card = hand[selectedHandIndex];
    const reductions = getAvailableReductionsFromBoard(me.zones);
    const actualCost = calcActualCost(card, reductions);
    const needCores = card.levels[0].core;
    const totalPay = actualCost + needCores;
    if (me.reserve < totalPay) {
      alert(`コア不足：必要${totalPay}（コスト${actualCost} + Lv1必要${needCores}）/ 手持ち${me.reserve}`);
      return;
    }
    setMe((m) => ({
      ...m,
      reserve: m.reserve - totalPay,
      trash: m.trash + actualCost,
      zones: m.zones.map((z, i) => (i === zoneIdx ? { card, cores: needCores, exhausted: false } : z)),
    }));
    const nh = [...hand];
    nh.splice(selectedHandIndex, 1);
    setHand(nh);
    setSelectedHandIndex(null);
  };

  const levelUp = (zoneIdx) => {
    if (!canSummon) return;
    const z = me.zones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const arr = z.card.levels;
    const i = arr.findIndex((l) => l.lv === curr.lv);
    const next = arr[i + 1];
    if (!next) return;
    const needMore = next.core - z.cores;
    if (needMore <= 0) return;
    if (me.reserve < needMore) {
      alert(`コア不足：Lv${curr.lv}→Lv${next.lv} に +${needMore} 必要`);
      return;
    }
    setMe((m) => ({
      ...m,
      reserve: m.reserve - needMore,
      zones: m.zones.map((zz, k) => (k === zoneIdx ? { ...zz, cores: next.core } : zz)),
    }));
  };

  const levelDown = (zoneIdx) => {
    if (!canSummon) return;
    const z = me.zones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const arr = z.card.levels;
    const i = arr.findIndex((l) => l.lv === curr.lv);
    const prev = arr[i - 1];
    if (!prev) return;
    const refund = z.cores - prev.core;
    setMe((m) => ({
      ...m,
      reserve: m.reserve + refund,
      zones: m.zones.map((zz, k) => (k === zoneIdx ? { ...zz, cores: prev.core } : zz)),
    }));
  };

  // AI側のブロック選択ロジック（プレイヤー攻撃時）
  function aiChooseBlockFor(attackerBP, attackerSymbols, forcedBlock = false) {
    const ready = opRef.current.zones
      .map((z, i) => (z && !z.exhausted ? { i, bp: getBaseBP(z) } : null))
      .filter(Boolean);
    if (ready.length === 0) return null;
    if (forcedBlock) {
      const killers = ready.filter((r) => r.bp >= attackerBP).sort((a, b) => a.bp - b.bp);
      if (killers.length > 0) return killers[0].i;
      // 破壊不可なら最大BPでブロック
      return ready.sort((a, b) => b.bp - a.bp)[0].i;
    }
    // 通常: 勝てるなら勝てる最小BP、勝てないなら致死のとき最大BP、そうでなければブロックしない
    const killers = ready.filter((r) => r.bp >= attackerBP).sort((a, b) => a.bp - b.bp);
    if (killers.length > 0) return killers[0].i;
    const lethal = attackerSymbols >= opRef.current.life;
    if (lethal) return ready.sort((a, b) => b.bp - a.bp)[0].i;
    return null;
  }

  // プレイヤーが攻撃する
  const attackWith = (zoneIdx) => {
    if (!canAttack) return;
    const z = meRef.current.zones[zoneIdx];
    if (!z || z.exhausted) return;
    const symbols = Math.max(0, z.card.symbolCount || 1);
    const atkBP = getAttackBP(z);
    const forced = mustForceBlock(z, "me", meRef, opRef);
    const blkIndex = aiChooseBlockFor(atkBP, symbols, forced);
    if (blkIndex === null) {
      applyUnblockedDamage("op", symbols, "me", zoneIdx);
    } else {
      resolveBattle("me", zoneIdx, blkIndex, atkBP);
      setAiLog((l) => [...l, `AIブロック: ゾーン${blkIndex + 1}（BP ${getBaseBP(opRef.current.zones[blkIndex])}）`]);
    }
  };

  const onZoneClick = (zoneIdx) => {
    if (me.zones[zoneIdx] === null) summonToZone(zoneIdx);
  };

  /* ---------- 敵（AI）のターン ---------- */
  const enemyTurn = async () => {
    const logs = [];
    // 0: コア
    setOp((o) => ({ ...o, reserve: o.reserve + 1 }));
    // 1: ドロー
    if (opDeck.length > 0) {
      const idx = Math.floor(Math.random() * opDeck.length);
      const c = opDeck[idx];
      const nd = [...opDeck];
      nd.splice(idx, 1);
      setOpDeck(nd);
      setOpHand((h) => [...h, c]);
    }
    // 2: リフレッシュ
    setOp((o) => ({
      ...o,
      reserve: o.reserve + o.trash,
      trash: 0,
      zones: o.zones.map((z) => (z ? { ...z, exhausted: false } : z)),
    }));
    // メインステップ用の思考状態を構築
    let sim = {
      me: structuredClone(meRef.current),
      op: structuredClone({
        ...opRef.current,
        reserve: opRef.current.reserve + 1 + opRef.current.trash,
        trash: 0,
        zones: opRef.current.zones.map((z) => (z ? { ...z, exhausted: false } : z)),
      }),
      opHand: [...opHand, ...(opDeck[0] ? [opDeck[0]] : [])],
      opDeckCount: Math.max(0, opDeck.length - 1),
    };
    // 3: メイン — AIが召喚/レベルを繰り返す
    for (let i = 0; i < 20; i++) {
      const mv = chooseBestMainMove(sim);
      if (!mv) break;
      logs.push(mv.type === "SUMMON"
        ? `AI召喚: ゾーン${mv.zoneIndex + 1}`
        : `AIレベルアップ: ゾーン${mv.zoneIndex + 1} (+${mv.needMore})`);
      if (mv.type === "SUMMON") {
        const card = sim.opHand[mv.handIndex];
        setOp((o) => ({
          ...o,
          reserve: o.reserve - mv.pay.totalPay,
          trash: o.trash + mv.pay.actualCost,
          zones: o.zones.map((z, i) => (i === mv.zoneIndex ? { card, cores: mv.pay.needCores, exhausted: false } : z)),
        }));
        setOpHand((h) => {
          const nh = [...h];
          nh.splice(mv.handIndex, 1);
          return nh;
        });
      } else if (mv.type === "LEVEL_UP") {
        setOp((o) => ({
          ...o,
          reserve: o.reserve - mv.needMore,
          zones: o.zones.map((z, i) => (i === mv.zoneIndex ? { ...z, cores: z.cores + mv.needMore } : z)),
        }));
      }
      sim = simulateMain(sim, mv);
    }
    // 4: アタック — 各スピリット順に攻撃宣言
    for (let i = 0; i < 4; i++) {
      const curr = opRef.current;
      const z = curr.zones[i];
      if (!z || z.exhausted) continue;
      const symbols = Math.max(0, z.card.symbolCount || 1);
      const atkBP = getAttackBP(z);
      const forced = mustForceBlock(z, "op", meRef, opRef);
      const readyDefs = meRef.current.zones.some((zz) => zz && !zz.exhausted);
      if (!readyDefs) {
        applyUnblockedDamage("me", symbols, "op", i);
        logs.push(`AI攻撃: ゾーン${i + 1}（シンボル${symbols}）→ ノーブロック`);
        continue;
      }
      // 人間にブロック選択を促す
      const choice = await waitForBlockChoice("op", i, atkBP, symbols, forced);
      // 念のためプロンプトを閉じる（残らないように）
      closeBlockPrompt();
      if (forced && (!choice || choice.type === "none")) {
        // ブロック必須なのに選択されなかった→利用可能なブロッカーから適当に選ぶ
        const readyList = meRef.current.zones
          .map((z2, j) => (z2 && !z2.exhausted ? j : null))
          .filter((j) => j !== null);
        if (readyList.length > 0) {
          const auto = readyList[0];
          resolveBattle("op", i, auto, atkBP);
          logs.push(`AI攻撃: ゾーン${i + 1} を 人間ゾーン${auto + 1} が強制ブロック`);
        } else {
          // ブロック不可
          applyUnblockedDamage("me", symbols, "op", i);
          logs.push(`AI攻撃: ゾーン${i + 1}（シンボル${symbols}）→ ブロック不可`);
        }
      } else if (!choice || choice.type === "none") {
        applyUnblockedDamage("me", symbols, "op", i);
        logs.push(`AI攻撃: ゾーン${i + 1}（シンボル${symbols}）→ ブロックなし`);
      } else {
        resolveBattle("op", i, choice.blocker, atkBP);
        logs.push(`AI攻撃: ゾーン${i + 1} を 人間ゾーン${choice.blocker + 1} がブロック`);
      }
    }
    setAiLog((l) => [...l, ...logs]);
    setPhase(0);
  };

  /* ---------- レンダリング ---------- */
  const phaseName = [
    "①コア",
    "②ドロー",
    "③リフレッシュ",
    "④メイン",
    "⑤アタック",
  ][phase];
  const nextDisabled = phase === 4;
  return (
    <div className="board">
      {/* === 自分側（左） === */}
      <section className="side my-side">
        <header className="hud hud-top">
          <span className="hud-item">フェーズ <b>{phaseName}</b></span>
          <span className="hud-item">LIFE <b>{me.life}</b></span>
          <span className="hud-item">RESERVE <b>{me.reserve}</b></span>
          <span className="hud-item">TRASH <b>{me.trash}</b></span>
          <span className="hud-item">CARD-TRASH <b>{me.cTrash.length}</b></span>
          <span className="spacer" />
          <button className="btn next-btn" onClick={nextStep} disabled={nextDisabled}>
            次のステップ
          </button>
          <button className="btn" onClick={enemyTurn}>敵のターン</button>
        </header>

        <div className="field">
          {me.zones.map((z, i) => {
            if (!z) {
              return (
                <div
                  key={i}
                  className={`zone ${selectedHandIndex !== null && canSummon ? "placeable" : ""}`}
                  onClick={() => onZoneClick(i)}
                >
                  <span>ゾーン{i + 1}</span>
                </div>
              );
            }
            const info = levelFromCores(z.card, z.cores);
            return (
              <div key={i} className={`zone filled ${z.exhausted ? "attacked" : ""}`}>
                <img src={z.card.img} alt={z.card.name} className="zone-card" />
                <div className="zone-badge">
                  Lv{info.lv} / BP {info.bp}
                </div>
                {z.exhausted && <div className="zone-flag">疲労</div>}
                <div className="zone-controls">
                  <button className="btn-small" onClick={() => levelDown(i)} disabled={!canSummon}>-</button>
                  <button className="btn-small" onClick={() => levelUp(i)} disabled={!canSummon}>+</button>
                  <button
                    className={`btn-small warn ${z.exhausted ? "disabled" : ""}`}
                    onClick={() => attackWith(i)}
                    disabled={!canAttack || !!z.exhausted}
                    title={
                      !canAttack
                        ? "アタックステップのみ"
                        : z.exhausted
                        ? "疲労中"
                        : "アタックする"
                    }
                  >
                    ATK
                  </button>
                </div>
              </div>
            );
          })}
        </div>
        {/* 手札ゾーン */}
        <footer className="hand hand-bottom">
          {hand.length === 0 ? (
            <span>手札ゾーン</span>
          ) : (
            <div className="hand-cards">
              {hand.map((card, idx) => (
                <img
                  key={card.deckIndex ?? `${card.id}-${idx}`}
                  src={card.img}
                  alt={card.name}
                  className={`card-img ${selectedHandIndex === idx ? "selected" : ""}`}
                  onClick={() => onHandClick(idx)}
                  draggable={false}
                  title={card.name}
                />
              ))}
            </div>
          )}
        </footer>
      </section>
      {/* 仕切り線 */}
      <div className="divider" />
      {/* === 相手側（右） === */}
      <section className="side op-side">
        <header className="hud hud-bottom">
          <span className="hud-item red">LIFE <b>{op.life}</b></span>
          <span className="hud-item red">RESERVE <b>{op.reserve}</b></span>
          <span className="hud-item red">TRASH <b>{op.trash}</b></span>
          <span className="hud-item red">CARD-TRASH <b>{op.cTrash.length}</b></span>
          <span className="spacer" />
          <span className="hud-item">敵手札 {opHand.length} 枚</span>
        </header>
        <div className="field">
          {op.zones.map((z, i) => {
            if (!z) return (
              <div key={i} className="zone">
                <span>{i + 1}ゾーン</span>
              </div>
            );
            const info = levelFromCores(z.card, z.cores);
            return (
              <div key={i} className={`zone filled ${z.exhausted ? "attacked" : ""}`}>
                <img src={z.card.img} alt={z.card.name} className="zone-card" />
                <div className="zone-badge">
                  Lv{info.lv} / BP {info.bp}
                </div>
                {z.exhausted && <div className="zone-flag">疲労</div>}
              </div>
            );
          })}
        </div>
        {/* AIログ */}
        {aiLog.length > 0 && (
          <div style={{ marginTop: 8, fontSize: 12, color: "#444" }}>
            <div style={{ fontWeight: 700, marginBottom: 4 }}>AIログ</div>
            <ul style={{ margin: 0, paddingLeft: 16 }}>
              {aiLog.slice(-8).map((t, i) => (
                <li key={i}>{t}</li>
              ))}
            </ul>
          </div>
        )}
      </section>
      {/* === ブロック選択ダイアログ === */}
      {blockPrompt && blockPrompt.defender === "me" && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,.35)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
          }}
        >
          <div style={{ background: "#fff", padding: 16, borderRadius: 12, width: 520 }}>
            <div style={{ fontWeight: 700, marginBottom: 8 }}>ブロック選択</div>
            <div style={{ fontSize: 14, marginBottom: 8 }}>
              敵のゾーン{blockPrompt.attackerZone + 1} が攻撃（BP {blockPrompt.attackerBP} / シンボル {blockPrompt.attackerSymbols}）
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 8 }}>
              {me.zones.map((z, i) => {
                if (!z || z.exhausted) {
                  return (
                    <button key={i} className="btn" style={{ opacity: 0.4 }} disabled>
                      {i + 1}：ブロック不可
                    </button>
                  );
                }
                const info = levelFromCores(z.card, z.cores);
                return (
                  <button
                    key={i}
                    className="btn"
                    onClick={() => {
                      const r = blockResolverRef.current;
                      if (r) r({ type: "block", blocker: i });
                      setBlockPrompt(null);
                      blockResolverRef.current = null;
                    }}
                    title={`${z.card.name} / Lv${info.lv} BP${info.bp}`}
                  >
                    {i + 1}：{z.card.name}（Lv{info.lv} BP{info.bp}）
                  </button>
                );
              })}
            </div>
            {!blockPrompt.forcedBlock && (
              <div style={{ display: "flex", gap: 8, marginTop: 12, justifyContent: "flex-end" }}>
                <button
                  className="btn"
                  onClick={() => {
                    const r = blockResolverRef.current;
                    if (r) r({ type: "none" });
                    setBlockPrompt(null);
                    blockResolverRef.current = null;
                  }}
                >
                  ブロックしない
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
